/* ═══════════════════════════════════════════════════════════
   14. 난이도(d) 자동 분류
   d = 1 기초 · 2 표준 · 3 심화
   문항에 d 가 직접 지정되어 있으면 그 값을 그대로 쓰고,
   없는 문항에만 아래 규칙을 적용해 back-fill 한다.

   [심화 3] 판단·최신 개정·수치 혼동
     · 사례 판단형("다음 사례", "가장 적절한", "거리가 먼")
     · 최신 개정 신호(2023~2025 / 개정 / 신설 / 폐지 / 통합)
     · 서로 다른 인원·기간 수치가 3개 이상 등장(혼동 유도형)
   [기초 1] 단일 사실 암기 — 회독으로 바로 붙는 문항
     · 두음·나열 단답(채점 키워드 4개 이상)
     · 해설 한 줄로 끝나는 단문 OX(28자 이하)
   [표준 2] 그 밖의 개념 구분·조문 매칭 (기본값)
   ═══════════════════════════════════════════════════════════ */
(function assignDifficulty(){
  const NUM = /(\d+\s*(?:만|천)?\s*명|\d+\s*(?:년|개월|일|시간|회|%|포인트|개))/g;
  const HARD_Q = /다음 사례|사례 중|가장 적절한|거리가 먼|판단 기준|옳게 연결/;
  const HARD_T = /202[3-5]|개정|신설|폐지|통합|특례/;
  const each = (arr, type) => arr.forEach(q => {
    if (q.d) return;                                   // 직접 지정된 난이도 우선
    const body = [q.q, (q.c || []).join(' '), q.e || '', typeof q.a === 'string' ? q.a : ''].join(' ');
    const nums = new Set((body.match(NUM) || []).map(x => x.replace(/\s/g, '')));
    if (HARD_Q.test(q.q) || HARD_T.test(body) || nums.size >= 3) { q.d = 3; return; }
    if (type === 'fill' && (q.k || []).length >= 4) { q.d = 1; return; }
    if (type === 'ox' && (q.e || '').length <= 28)  { q.d = 1; return; }
    q.d = 2;
  });
  each(CPPG.mcq, 'mcq'); each(CPPG.ox, 'ox'); each(CPPG.fill, 'fill');
})();

