  { s:'s2', t:'정보주체 권리·구제', d:3, q:'손해배상 제도의 연결이 옳은 것은?', c:['징벌적 — 300만원 이내','법정 — 손해액 5배','징벌적 — 손해액 5배 이내 / 법정 — 300만원 이내','단체소송 — 손해배상 청구 가능'], a:2, e:'단체소송은 권리침해 중지 청구 중심이다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'생체인식정보와 여권번호의 분류를 옳게 연결한 것은?', c:['둘 다 고유식별정보','둘 다 민감정보','생체인식 — 민감정보 / 여권번호 — 고유식별정보','생체인식 — 고유식별정보 / 여권번호 — 민감정보'], a:2, e:'2024년 생체인식정보가 민감정보로 신설되었다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'인증·평가 제도의 연결이 옳지 않은 것은?', c:['ISMS-P — 민관 공통 인증·심사','보호수준 평가 — 공공기관 대상','ISO 27701 — 27001 확장(PIMS)','PIA — 민간 사업자 의무'], a:3, e:'PIA 의무는 공공기관이며 민간은 권장이다.' },
  { s:'s2', t:'동의 제도', d:3, q:'동의 실무에 대한 설명으로 옳지 않은 것은?', c:['14세 미만은 법정대리인 동의가 필요하다','선택 동의를 거부하면 서비스 제공을 거부할 수 있다','법정대리인 확인에 필요한 최소 정보는 동의 없이 수집할 수 있다','중요 내용은 9포인트 이상으로 구분 표시한다'], a:1, e:'선택 동의 거부를 이유로 서비스를 거부하면 위법이다.' }
