/* ── 기출 유형 문항 — 〈보기〉 ㄱㄴㄷ 조합형 · 사례 지문형 · 짝 연결형 ──
   실제 CPPG 기출은 지문이 길고 "옳은 것을 모두 고른 것", "옳게 묶인 것" 형태가 많다.
   \n 은 렌더러가 .qtext 의 white-space:pre-wrap 로 줄바꿈 그대로 표시한다. */
CPPG.mcq.push(

  /* ─── 〈보기〉 조합형 ─── */
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 개인정보보호법상 "개인정보"에 해당하는 것을 모두 고른 것은?\n\nㄱ. 사망한 자의 진료 기록\nㄴ. 살아있는 개인의 휴대전화번호\nㄷ. 다른 정보와 쉽게 결합하여 특정 개인을 알아볼 수 있는 IP 주소\nㄹ. 법인의 사업자등록번호\nㅁ. 추가 정보를 사용하여 복원할 수 있는 가명정보', c:['ㄱ, ㄴ, ㄷ','ㄴ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ'], a:1, e:'사망자·법인 정보는 개인정보가 아니며, 가명정보는 개인정보에 포함된다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 민감정보에 해당하는 것을 모두 고른 것은?\n\nㄱ. 노동조합의 가입·탈퇴\nㄴ. 여권번호\nㄷ. 건강 및 성생활에 관한 정보\nㄹ. 유전정보\nㅁ. 운전면허번호', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄷ, ㄹ, ㅁ'], a:1, e:'여권번호·운전면허번호는 고유식별정보다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 〈보기〉에서 GDPR의 적법 처리 근거(6가지)에 해당하는 것을 모두 고른 것은?\n\nㄱ. 정보주체의 동의\nㄴ. 계약의 체결·이행\nㄷ. 적정성 결정\nㄹ. 컨트롤러의 정당한 이익\nㅁ. 표준계약조항(SCC)', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'적정성 결정·SCC는 국외이전 수단이지 처리 근거가 아니다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음 〈보기〉에서 정보주체의 동의 없이 개인정보를 수집·이용할 수 있는 경우를 모두 고른 것은?\n\nㄱ. 법률에 특별한 규정이 있는 경우\nㄴ. 재화·서비스의 홍보 및 판매 권유를 위한 경우\nㄷ. 계약의 체결·이행을 위해 불가피하게 필요한 경우\nㄹ. 정보주체의 생명·신체·재산의 이익을 위해 급박히 필요한 경우\nㅁ. 통계작성 및 학술연구 등을 위해 특정 개인을 알아볼 수 없는 형태로 처리하는 경우', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㄹ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄹ, ㅁ'], a:1, e:'홍보·판매 권유는 별도 동의 대상이다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음 〈보기〉에서 반드시 다른 동의와 구분하여 별도로 받아야 하는 동의를 모두 고른 것은?\n\nㄱ. 개인정보 수집·이용 동의\nㄴ. 개인정보 제3자 제공 동의\nㄷ. 민감정보 처리 동의\nㄹ. 고유식별정보 처리 동의\nㅁ. 재화·서비스 홍보 및 판매 권유 목적 처리 동의', c:['ㄱ, ㄴ','ㄷ, ㄹ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ'], a:1, e:'민감·고유식별·홍보 목적은 별도 동의가 필요하다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 〈보기〉에서 개인정보보호법상 정보주체의 권리에 해당하는 것을 모두 고른 것은?\n\nㄱ. 개인정보 처리에 관한 정보를 제공받을 권리\nㄴ. 개인정보의 열람을 요구할 권리\nㄷ. 개인정보 처리의 정지를 요구할 권리\nㄹ. 자동화된 결정에 대해 거부하거나 설명을 요구할 권리\nㅁ. 개인정보처리자의 임직원을 징계할 것을 요구할 권리', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ, ㅁ'], a:0, e:'징계 요구권은 정보주체의 권리가 아니다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'다음 〈보기〉에서 개인정보 유출 시 정보주체에게 통지해야 할 사항을 모두 고른 것은?\n\nㄱ. 유출된 개인정보의 항목\nㄴ. 유출된 시점과 그 경위\nㄷ. 정보주체가 피해를 최소화하기 위해 할 수 있는 방법\nㄹ. 유출 원인을 제공한 담당자의 인적사항\nㅁ. 개인정보처리자의 대응조치 및 피해 구제절차', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄹ','ㄷ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ, ㅁ'], a:0, e:'담당자 인적사항은 통지 항목이 아니다. 신고 접수처와 책임자 연락처는 포함된다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 〈보기〉에서 개인정보 "위탁"에 해당하는 사례를 모두 고른 것은?\n\nㄱ. 고객센터 상담 업무를 외부 업체에 맡김\nㄴ. 계열사에 회원 정보를 마케팅 목적으로 넘김\nㄷ. 클라우드 사업자에게 데이터 보관을 맡김\nㄹ. 제휴사에 회원 정보를 제공해 제휴사 상품을 판매하게 함\nㅁ. 청구서 인쇄·발송 업무를 외부 업체에 맡김', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄷ, ㄹ, ㅁ'], a:1, e:'ㄴ·ㄹ은 받는 자의 목적을 위한 처리이므로 제3자 제공이다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 〈보기〉에서 개인정보 처리 위탁 계약서에 반드시 포함해야 할 사항을 모두 고른 것은?\n\nㄱ. 위탁업무 수행 목적 외 개인정보 처리 금지\nㄴ. 재위탁 제한\nㄷ. 수탁자의 매출액 및 재무제표\nㄹ. 개인정보에 대한 접근 제한 등 안전성 확보조치\nㅁ. 수탁자가 준수해야 할 의무 위반 시 손해배상 등 책임', c:['ㄱ, ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'두음 목·제·기·관·손 — 수탁자의 재무 정보는 필수 기재사항이 아니다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 〈보기〉에서 개인정보를 국외로 이전할 수 있는 적법 사유를 모두 고른 것은?\n\nㄱ. 정보주체로부터 국외 이전에 관한 별도의 동의를 받은 경우\nㄴ. 법률·조약에 개인정보 국외 이전에 관한 규정이 있는 경우\nㄷ. 개인정보위가 고시한 인증을 받은 경우\nㄹ. 이전받는 국가의 물가가 낮은 경우\nㅁ. 계약의 체결·이행을 위해 필요한 경우로서 정보주체에게 알린 경우', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄹ','ㄷ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ'], a:0, e:'동·법·인·계·공 5사유 — ㄹ은 근거가 되지 않는다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 〈보기〉에서 개인정보의 안전성 확보조치 기준상 "규모(인원)에 따라 달라지는" 조항을 모두 고른 것은?\n\nㄱ. 내부 관리계획 수립 생략\nㄴ. 암호키 관리절차 수립\nㄷ. 인터넷망 차단조치\nㄹ. 개인정보 파기 시점(5일 이내)\nㅁ. 접속기록 2년 이상 보관', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'파기 5일은 규모와 무관한 공통 의무다.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 〈보기〉에서 접속기록에 반드시 포함해야 할 항목을 모두 고른 것은?\n\nㄱ. 계정(식별자)\nㄴ. 접속일시\nㄷ. 접속지 정보\nㄹ. 수행업무\nㅁ. 정보주체의 동의 여부', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'계·일·지·업 — 동의 여부·처리 목적은 접속기록 항목이 아니다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 〈보기〉에서 KISA 권고상 사용을 권장하는 알고리즘을 모두 고른 것은?\n\nㄱ. AES-256\nㄴ. SEED\nㄷ. MD5\nㄹ. SHA-256\nㅁ. SHA-1', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'MD5·SHA-1은 사용 금지 대상이다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 〈보기〉에서 ISMS-P 인증에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 통제 항목은 101개이며 16 + 64 + 21로 구성된다\nㄴ. 인증 유효기간은 3년이며 사후심사는 3년에 1회 받는다\nㄷ. 주관 기관은 KISA, 개인정보보호위원회, 과학기술정보통신부다\nㄹ. 심사 종류는 최초·사후·갱신 심사로 구분된다\nㅁ. ISMS 인증의 통제 항목은 80개다', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㄹ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ, ㅁ'], a:1, e:'사후심사는 연 1회 이상이다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'다음 〈보기〉에서 개인정보 영향평가(PIA)에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 5단계는 사전 준비 → 자료 수집 → 위험 분석 → 대책 수립 → 검토·이행이다\nㄴ. 위험 분석은 자산·위협·취약점·영향의 4요소로 수행한다\nㄷ. 시스템 구축이 완료된 후에 수행하는 사후 평가다\nㄹ. 공공기관이 5만명 이상의 민감정보·고유식별정보를 처리하는 파일은 의무 대상이다\nㅁ. 민간 사업자도 법상 의무 대상이다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'PIA는 사전 평가이며 민간은 권장이다.' },
  { s:'s5', t:'위험관리', d:3, q:'다음 〈보기〉에서 위험 처리 전략과 설명의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 수용 — 위험을 그대로 받아들임(DoA 이하)\nㄴ. 감소 — 보호대책을 적용해 위험을 낮춤\nㄷ. 회피 — 보험에 가입해 위험을 넘김\nㄹ. 전가 — 위험이 발생하는 활동 자체를 중단함\nㅁ. 전가를 하더라도 법적 책임은 개인정보처리자에게 남는다', c:['ㄱ, ㄴ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄷ, ㅁ','ㄷ, ㄹ, ㅁ'], a:0, e:'ㄷ과 ㄹ의 설명이 서로 바뀌었다.' },

  /* ─── 사례 지문형 ─── */
  { s:'s3', t:'제공·위탁', d:3, q:'A 온라인 쇼핑몰은 다음과 같이 개인정보를 처리하고 있다.\n\n· 고객 상담 업무를 B 콜센터 업체에 맡기고 있다\n· 계열사 C사에 회원 정보를 제공해 C사 상품을 홍보하도록 하고 있다\n· 상품 배송을 위해 D 택배사에 수령인 정보를 전달한다\n\n이에 대한 설명으로 옳은 것은?', c:['B·D는 제3자 제공, C는 위탁에 해당한다','B·D는 위탁이므로 공개로 갈음할 수 있고, C는 별도 동의가 필요하다','세 경우 모두 정보주체의 별도 동의가 필요하다','세 경우 모두 위탁이므로 동의가 필요 없다'], a:1, e:'판단 기준은 누구의 목적으로 처리하는가이다. C는 받는 자의 목적이므로 제3자 제공.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'B 기업은 해킹으로 회원 3,000명의 이름·연락처·주민등록번호가 유출된 사실을 인지하였다.\n\n이 상황에서 B 기업이 취해야 할 조치로 가장 적절한 것은?', c:['정보주체 통지는 30일 이내, 기관 신고는 하지 않아도 된다','정보주체에게 72시간 이내 통지하고, 1천명 이상이므로 개인정보위·KISA에 72시간 내 신고한다','피해가 확인된 뒤에 통지·신고하면 된다','기관 신고만 하고 정보주체 통지는 생략할 수 있다'], a:1, e:'통지 72시간, 신고 기준 1천명 — 1차 신고 후 보강신고를 한다.' },
  { s:'s4', t:'접속기록', d:3, q:'C 기업은 정보주체 8만명의 개인정보를 처리하며, 그중 일부는 고유식별정보를 포함한다.\n현재 접속기록을 1년간 보관하고 분기마다 점검하고 있다.\n\n이 기업의 조치에 대한 평가로 옳은 것은?', c:['보관 기간과 점검 주기 모두 적정하다','보관 기간은 2년 이상이어야 하고 점검은 월 1회 이상이어야 한다','보관 기간은 적정하나 점검은 연 1회면 된다','보관 기간은 3년이어야 한다'], a:1, e:'5만명 이상 또는 고유식별·민감정보 처리 시 2년, 점검은 월 1회 이상.' },
  { s:'s4', t:'암호화', d:3, q:'D 기업의 개발자가 다음과 같이 시스템을 구성하였다.\n\n· 회원 비밀번호를 양방향 암호화하여 저장\n· 주민등록번호를 평문으로 저장하되 접근권한만 제한\n· 로그인 구간에 SSL/TLS 적용\n\n이 구성에 대한 지적으로 옳은 것은?', c:['비밀번호는 일방향 암호화해야 하고, 주민등록번호는 예외 없이 암호화해야 한다','비밀번호는 평문 저장해도 접근통제만 하면 된다','주민등록번호는 접근권한 제한으로 충분하다','SSL/TLS는 불필요한 조치다'], a:0, e:'비밀번호=일방향, 주민등록번호=무조건 암호화.' },
  { s:'s2', t:'동의 제도', d:3, q:'E 서비스는 회원가입 화면에서 다음과 같이 동의를 받고 있다.\n\n· 수집·이용, 마케팅 활용, 제3자 제공 동의를 하나의 체크박스로 묶어 받는다\n· 마케팅 동의를 하지 않으면 가입할 수 없도록 하였다\n· 중요한 내용은 본문과 같은 크기·색으로 표시하였다\n\n위반 사항으로 옳게 묶인 것은?', c:['묶음 동의 · 선택 동의 거부 시 서비스 거부 · 중요 내용 표시 미흡','묶음 동의만 위반','중요 내용 표시만 위반','위반 사항이 없다'], a:0, e:'분리 동의 원칙, 선택 동의 거부를 이유로 한 거부 금지, 9포인트 이상 구분 표시.' },
  { s:'s3', t:'보유·파기', d:3, q:'F 쇼핑몰은 회원 탈퇴 회원의 개인정보를 다음과 같이 처리하려 한다.\n\n· 탈퇴 즉시 모든 개인정보를 삭제\n· 전자상거래법상 계약·청약철회 기록도 함께 삭제\n· 삭제는 파일 삭제 후 휴지통 비우기로 수행\n\n이에 대한 지적으로 옳은 것은?', c:['처리 방식이 모두 적정하다','법령상 보존 의무가 있는 기록은 분리 보관해야 하고, 파기는 복원 불가능한 방법이어야 한다','보존 기록도 즉시 삭제하는 것이 맞다','파기는 30일 이내에 하면 된다'], a:1, e:'파기 5일 이내 + 복원 불가 방법, 법령 보존분은 분리 저장·관리.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'G 헬스장은 회원 안전을 이유로 다음과 같이 CCTV를 운영한다.\n\n· 운동 공간과 탈의실에 각각 카메라를 설치\n· 안내판에는 "CCTV 촬영 중" 문구만 표시\n· 상담 내용을 확인하기 위해 녹음 기능을 켬\n\n위반 사항으로 옳게 묶인 것은?', c:['탈의실 설치 · 안내판 표시사항 누락 · 녹음 기능 사용','탈의실 설치만 위반','녹음 기능만 위반','위반 사항이 없다'], a:0, e:'사생활 침해 우려 장소 설치 금지, 안내판 4항목, 녹음 금지.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'H 공공기관은 다음과 같이 개인정보 관리 활동을 계획했다.\n\n· 신규 시스템 구축을 마친 뒤 개인정보 영향평가를 수행\n· ISMS-P 인증을 받으면 보호수준 평가는 면제된다고 판단\n· 위험 분석 시 자산·위협·취약점만 고려\n\n이에 대한 지적으로 옳은 것은?', c:['영향평가는 구축 전에 수행해야 하고, 보호수준 평가는 별개 제도이며, 위험 분석에는 영향도 포함된다','모두 적정한 계획이다','영향평가 시점만 잘못되었다','보호수준 평가는 ISMS-P로 대체 가능하다'], a:0, e:'PIA는 사전 평가, 보호수준 평가는 공공기관 대상 별도 제도.' },
  { s:'s3', t:'광고성 정보', d:3, q:'I 쇼핑몰의 마케팅 담당자가 다음과 같이 문자를 발송하려 한다.\n\n· 수신동의한 회원에게 22시에 할인 안내 문자 발송\n· 2년 전 수신거부한 회원에게 "기간이 지났으므로" 재발송\n· 제목에 (광고) 표기 없이 발송\n\n위반 사항으로 옳게 묶인 것은?', c:['야간 전송 · 수신거부자 재발송 · (광고) 표기 누락','야간 전송만 위반','수신거부자 재발송만 위반','위반 사항이 없다'], a:0, e:'21~08시 별도 동의, 수신거부는 기간 제한 없이 전송 금지, (광고) 표기 의무.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'J 기업(중소기업)은 정보주체 60만명의 개인정보를 처리하며, 직전 3개월간 일일평균 처리량은 20만명 수준이다.\n\n이 기업에 적용되는 의무로 옳은 것은?', c:['인터넷망 차단조치 의무가 있다','암호키 관리절차 수립 의무가 있다','접속기록을 2년 이상 보관해야 한다','내부 관리계획을 생략할 수 있다'], a:2, e:'망분리는 일일평균 100만명 이상, 암호키(중소)는 100만명 이상, 내부 관리계획 생략은 1만명 미만.' },

  /* ─── 짝 연결·복합 판단형 ─── */
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 중 원칙 체계와 두음의 연결이 옳게 묶인 것은?', c:['OECD 8원칙 — 합·목·최·정·저·무·책','GDPR 7원칙 — 수·정·목·이·안·공·참·책','개인정보보호법 8원칙 — 수·필·정·기·안·공·정·익','NIST CSF — 사·자·위·대·검'], a:2, e:'OECD=수정목이안공참책, GDPR=합목최정저무책, NIST=식보탐대복, PIA=사자위대검.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 중 주기·기간의 연결이 모두 옳게 묶인 것은?', c:['접속기록 보관 1년 · 점검 월 1회 · 백신 검사 매일 1회 · 내부 관리계획 점검 연 1회','접속기록 보관 3년 · 점검 분기 1회 · 백신 검사 주 1회 · 내부 관리계획 점검 연 2회','접속기록 보관 2년(일괄) · 점검 연 1회 · 백신 검사 월 1회 · 권한기록 1년','접속기록 보관 1년 · 점검 연 1회 · 백신 검사 매일 1회 · 권한기록 5년'], a:0, e:'권한 부여·변경·말소 기록은 3년이다.' },
  { s:'s2', t:'감독기구·제재', d:3, q:'다음 중 제재와 수준의 연결이 옳게 묶인 것은?', c:['과징금 — 전체 매출액의 3% 이하 / 가명정보 재식별 — 3년 이하 징역','과징금 — 관련 매출액의 3% / 재식별 — 5년 이하 징역','과태료 — 전체 매출액의 3% / 부정 취득 — 3년 이하 징역','징벌적 손해배상 — 300만원 이내 / 법정 손해배상 — 5배 이내'], a:0, e:'부정 취득·제공 5년·5천만원, 징벌적 5배, 법정 300만원.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 중 기간 기준의 연결이 옳게 묶인 것은?', c:['간접수집 통지 3개월 · 파기 5일 · 분쟁조정 60일','간접수집 통지 5일 · 파기 3개월 · 분쟁조정 30일','간접수집 통지 1개월 · 파기 5일 · 분쟁조정 90일','간접수집 통지 3개월 · 파기 30일 · 분쟁조정 60일'], a:0, e:'가장 자주 뒤바뀌는 세 수치다.' },
  { s:'s5', t:'국제표준·프레임워크', d:3, q:'다음 중 표준·제도와 용도의 연결이 옳게 묶인 것은?', c:['ISO 27001 — ISMS(14개 통제영역) / ISO 27701 — PIMS(27001 확장) / ISO 19011 — 감사 표준','ISO 27018 — 프라이버시 프레임워크 / ISO 29100 — 클라우드 PII','ISO 27701 — 감사 표준 / ISO 19011 — PIMS','ISO 29100 — ISMS 인증 기준 / ISO 27001 — 프라이버시 프레임워크'], a:0, e:'29100 프레임워크, 27018 클라우드 PII 보호.' },
  { s:'s2', t:'법체계·원칙', d:3, q:'다음 중 개인정보보호법과 개별 법률의 관계에 대한 설명으로 옳은 것은?', c:['개인정보보호법이 항상 우선한다','개별 분야법(특별법)이 있으면 특별법이 우선 적용된다','개별법과 충돌하면 정보주체가 선택한다','시행령이 법률보다 우선한다'], a:1, e:'개인정보보호법은 일반법(모법)이다.' }
);

